SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, category, SORT_ARRAY(COLLECT_SET(category)) AS category_list, SIZE(COLLECT_SET(brand)) AS num_brands, COUNT(DISTINCT category) AS distinct_categories, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS cost_per_globex, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids FROM products GROUP BY DATE_TRUNC('WEEK', launch_date), category
